provenance.sourcePrompt:
Newspaper front-page OPENING card. 6s, 1920x1080, SILENT. IDENTICAL layout, font sizes and visual style to the closing card — same newspaper masthead design, same 80px headline, same column structure, same scan lines + halftone + vignette. Background is a portrait photo (not video). Ken Burns slow push on the portrait. Opening content: masthead says "The Biographical Record", headline is "BENEDICT CUMBERBATCH", subhead is the hook line, columns introduce the subject
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,700;0,900;1,400&family=Inter:wght@300;400&display=swap" rel="stylesheet">
<style>
root{--oxblood:#963f43;--ivory:#e7e0d4;--muted:#9b948a;}
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#0b0d0e;}
#scene{position:relative;display:flex;align-items:center;justify-content:center;}
/* portrait — Ken Burns via GSAP */
#bg{
position:absolute;top:0;left:0;width:100%;height:100%
object-fit:cover;z-index:1
transform-origin:50% 42%
filter:grayscale(70%) brightness(0.48) sepia(20%)
}
/* scan lines — identical to closing card */
#lines{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:2
background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,0,0,0.07) 3px,rgba(0,0,0,0.07) 4px)
pointer-events:none
}
/* halftone dots */
#dots{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:3
background-image:radial-gradient(circle,rgba(200,180,140,0.06) 1px,transparent 1px)
background-size:5px 5px;pointer-events:none
}
/* vignette */
#vig{
position:absolute;top:0;left:0;width:100%;height:100%;z-index:4
background:radial-gradient(ellipse at center,transparent 30%,rgba(0,0,0,0.78) 100%)
}
#fade{position:absolute;top:0;left:0;width:100%;height:100%;z-index:50;background:#000;opacity:0;pointer-events:none;}
/* newspaper card — same dimensions as closing card */
#paper{
position:relative;z-index:10
width:1080px
max-height:860px
display:flex;flex-direction:column
align-items:center
opacity:0
}
/* masthead — identical to closing */
#mhead{
width:100%;text-align:center
border-top:2px solid rgba(231,224,212,0.85)
border-bottom:1px solid rgba(231,224,212,0.50)
padding:10px 0 8px
}
#pname{
font-family:'Playfair Display',Georgia,serif
font-size:20px;font-weight:400
color:var(--ivory);letter-spacing:0.44em;text-transform:uppercase
}
#dline{
font-family:'Playfair Display',Georgia,serif
font-size:12px;font-style:italic
color:var(--muted);letter-spacing:0.14em;margin-top:3px
}
#mbar{width:100%;height:3px;background:rgba(231,224,212,0.80);margin:7px 0 16px;opacity:0;}
/* headline — same 80px 900 weight */
#hl{
font-family:'Playfair Display',Georgia,serif
font-size:80px;font-weight:900
color:var(--ivory);line-height:0.95
letter-spacing:-0.01em;text-align:center
margin-bottom:14px;opacity:0
}
/* subhead — same 18px italic */
#sh{
font-family:'Playfair Display',Georgia,serif
font-size:18px;font-weight:400;font-style:italic
color:rgba(231,224,212,0.75)
text-align:center;letter-spacing:0.03em
margin-bottom:14px;opacity:0
}
/* mid rule */
#mr{width:100%;height:1px;background:rgba(231,224,212,0.30);margin-bottom:14px;opacity:0;}
/* columns — same 14px */
#cols{display:flex;gap:36px;width:100%;opacity:0;}
col{
flex:1;font-family:'Playfair Display',Georgia,serif
font-size:14px;font-weight:400
color:rgba(200,190,170,0.72)
line-height:1.65;letter-spacing:0.015em;text-align:justify
}
cr{width:1px;background:rgba(231,224,212,0.18);flex-shrink:0;}
/* bottom rule */
#br{width:100%;height:1px;background:rgba(231,224,212,0.30);margin-top:14px;opacity:0;}
/* tagline — same oxblood */
#tl{
font-family:'Playfair Display',Georgia,serif
font-size:12px;font-weight:400
color:var(--oxblood);letter-spacing:0.34em
text-transform:uppercase;text-align:center
margin-top:8px;opacity:0
}
</style>
</head>
<body>
<div id="scene">
<img id="bg" src="{{heroImg}}" alt="">
<div id="lines"></div>
<div id="dots"></div>
<div id="vig"></div>
<div id="fade"></div>
<div id="paper">
<div id="mhead">
<div id="pname">The Biographical Record</div>
<div id="dline">London, England &nbsp;·&nbsp; Est. 1976 &nbsp;·&nbsp; A Life in Full</div>
</div>
<div id="mbar"></div>
<div id="hl">BENEDICT<br>CUMBERBATCH</div>
<div id="sh">The cerebral outsider who became<br>the face of a generation's heroes.</div>
<div id="mr"></div>
<div id="cols">
<div class="col">Born 19 July 1976 in Hammersmith, London. Son of actors Timothy Carlton and Wanda Ventham. Educated at Harrow. Trained at Victoria University of Manchester and RADA.</div>
<div class="cr"></div>
<div class="col">Stage. Screen. Strange dimensions. A career built on patience, precision, and an intelligence that proved — once and for all — that it could be electric.</div>
</div>
<div id="br"></div>
<div id="tl">London · 1976</div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
/* Ken Burns on portrait */
tl.fromTo('#bg'
{scale:1.0, transformOrigin:'50% 42%'}
{scale:1.05, duration:6, ease:'none'}, 0)
/* paper slides up and fades in */
tl.to('#paper',{opacity:1,y:0,duration:0.7,ease:'power3.out'
startAt:{opacity:0,y:20}}, 0.4)
tl.to('#mbar', {opacity:1,scaleX:1,duration:0.45,ease:'expo.out'
startAt:{opacity:0,scaleX:0,transformOrigin:'left'}}, 0.6)
tl.to('#hl',   {opacity:1,y:0,duration:0.6,ease:'power3.out'
startAt:{opacity:0,y:14}}, 0.9)
tl.to('#sh',   {opacity:1,duration:0.45,ease:'power2.out'}, 1.42)
tl.to('#mr',   {opacity:1,duration:0.35,ease:'power2.out'}, 1.72)
tl.to('#cols', {opacity:1,y:0,duration:0.55,ease:'power2.out'
startAt:{opacity:0,y:8}}, 1.90)
tl.to('#br',   {opacity:1,duration:0.35,ease:'power2.out'}, 2.35)
tl.to('#tl',   {opacity:1,duration:0.45,ease:'power2.out'}, 2.60)
/* exit */
tl.to('#paper',{opacity:0,y:-18,duration:0.55,ease:'power2.in'}, 5.2)
tl.to('#fade', {opacity:1,duration:0.7,ease:'power2.inOut'}, 5.4)
})
</script>
</body>
</html>
```
